css:
:root {
  --page-1: #000000;
  --page-2: #000000;
  --page-3: #000000;
  --glass-card: rgba(32, 32, 34, 0.72);
  --glass-card-soft: rgba(22, 22, 24, 0.64);
  --glass-section: rgba(255, 255, 255, 0.065);
  --glass-label: rgba(255, 255, 255, 0.055);
  --glass-line: rgba(255, 255, 255, 0.13);
  --glass-edge: rgba(255, 255, 255, 0.18);
  --glass-shadow: rgba(0, 0, 0, 0.42);
  --text-main: #edf1f7;
  --text-muted: #a7a7ad;
  --accent-blue: #7ab7ff;
  --accent-violet: #b9a2ff;
  --accent-amber: #f0c674;
  --code-bg: rgba(8, 8, 9, 0.72);
  --code-text: #e9eef7;
  --code-inline-bg: rgba(255, 255, 255, 0.08);
  --code-green: #9bd88f;
}

.card,
.card.nightMode,
.nightMode .card {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
  font-size: 17px;
  line-height: 1.6;
  text-align: left;
  color: var(--text-main) !important;
  min-height: 100vh;
  padding: 1.35rem;
  max-width: 760px;
  margin: 0 auto;
  background: #000000 !important;
}

.anki-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1rem;
  border: 1px solid var(--glass-edge);
  border-radius: 26px;
  background: linear-gradient(145deg, var(--glass-card), var(--glass-card-soft));
  box-shadow:
    0 22px 56px var(--glass-shadow),
    inset 0 1px 0 rgba(255, 255, 255, 0.16),
    inset 0 -1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(24px) saturate(1.25);
  -webkit-backdrop-filter: blur(24px) saturate(1.25);
  overflow: hidden;
}

.anki-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(125deg, rgba(255,255,255,0.13), transparent 34%, transparent 76%, rgba(255,255,255,0.055));
  opacity: 0.82;
}

.answer-header,
.card-section,
hr#answer {
  position: relative;
  z-index: 1;
}

.answer-header {
  text-align: center;
  margin-bottom: 0.1rem;
  padding: 0.35rem 0.4rem 0.15rem;
}

.category-label {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.70em;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--accent-violet);
  margin-bottom: 0.65rem;
}

.category-icon {
  color: var(--accent-violet);
  flex-shrink: 0;
}

.question-text {
  font-size: 1.22em;
  font-weight: 750;
  color: var(--text-main) !important;
  line-height: 1.42;
  letter-spacing: -0.02em;
}

.question-text-small {
  font-size: 0.96em;
  font-weight: 560;
  color: var(--text-muted) !important;
  line-height: 1.46;
}

hr#answer {
  border: none;
  height: 1px;
  margin: 0.15rem 0.25rem;
  background: linear-gradient(90deg, transparent, var(--glass-line), transparent);
}

.card-section {
  background: var(--glass-section);
  border: 1px solid var(--glass-line);
  border-radius: 18px;
  overflow: hidden;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.10),
    0 8px 22px rgba(0, 0, 0, 0.12);
  backdrop-filter: blur(16px) saturate(1.15);
  -webkit-backdrop-filter: blur(16px) saturate(1.15);
}

.section-label {
  display: flex;
  align-items: center;
  gap: 0.42rem;
  font-size: 0.70em;
  font-weight: 720;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted) !important;
  background: var(--glass-label);
  border-bottom: 1px solid var(--glass-line);
  padding: 0.48rem 0.95rem;
}

.section-label svg {
  flex-shrink: 0;
  color: var(--accent-blue);
}

.section-content {
  padding: 0.82rem 1rem;
  text-align: left;
  color: var(--text-main) !important;
}

pre {
  background: var(--code-bg);
  border: 1px solid var(--glass-line);
  border-radius: 14px;
  padding: 0.9rem 1rem;
  overflow-x: auto;
  margin: 0;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07);
}

pre code {
  font-family: "SF Mono", "JetBrains Mono", "Fira Code", monospace;
  font-size: 0.85em;
  color: var(--code-text) !important;
  line-height: 1.72;
  background: none;
  border: none;
  padding: 0;
}

code {
  font-family: "SF Mono", "JetBrains Mono", "Fira Code", monospace;
  font-size: 0.85em;
  background: var(--code-inline-bg);
  color: var(--code-green) !important;
  padding: 0.14em 0.42em;
  border-radius: 7px;
  border: 1px solid var(--glass-line);
}

b, strong { color: var(--accent-amber) !important; }
i, em     { color: var(--accent-violet) !important; }

a { color: var(--accent-blue) !important; text-decoration: none; }
a:hover { text-decoration: underline; }

.cloze {
  color: var(--accent-blue) !important;
  font-weight: 800;
  border-bottom: 2px solid rgba(122, 183, 255, 0.34);
  padding-bottom: 1px;
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .anki-card,
  .card-section {
    background: rgba(31, 36, 49, 0.96);
  }
}
